<main class="mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8">
  <div><p class="text-[10px] font-black uppercase tracking-[.2em] text-violet-300">Accounts</p><h1 class="mt-2 text-3xl font-black">Users & teams</h1><p class="mt-2 text-sm text-slate-400">Search player accounts and manage active/suspended status. Admin roles are provisioned only from the server CLI.</p></div>
  <form method="get" class="glass-card mt-5 flex flex-wrap items-end gap-3 rounded-2xl p-4"><input type="hidden" name="page" value="admin-users"><label class="min-w-48 flex-1 text-xs font-bold text-slate-400">Search players<input class="form-control mt-2" name="q" maxlength="80" value="<?= h($search) ?>" placeholder="Email or player name"></label><label class="min-w-36 text-xs font-bold text-slate-400">Status<select class="form-control mt-2" name="status"><option value="all">All</option><option value="active" <?= $statusFilter==='active'?'selected':'' ?>>Active</option><option value="suspended" <?= $statusFilter==='suspended'?'selected':'' ?>>Suspended</option></select></label><button class="btn-primary rounded-xl px-5 py-3 text-sm font-black">Search</button></form>
  <div class="glass-card mt-5 overflow-hidden rounded-2xl"><div class="table-wrap"><table class="w-full text-left text-xs"><thead class="bg-black/20 text-[10px] uppercase tracking-wider text-slate-500"><tr><th class="px-4 py-4">Player</th><th class="px-4 py-4">Account</th><th class="px-4 py-4">Role</th><th class="px-4 py-4">Joined</th><th class="px-4 py-4">Wallet</th><th class="px-4 py-4">Action</th></tr></thead><tbody class="divide-y divide-white/[.07]"><?php foreach($users as $user): ?><tr><td class="px-4 py-4"><p class="font-black"><?= h($user['display_name'] ?: 'Unnamed player') ?></p><p class="mt-1 text-[10px] text-slate-500"><?= h($user['email']) ?></p></td><td class="px-4 py-4"><span class="badge <?= $user['status']==='active'?'badge-open':'badge-closed' ?>"><?= h($user['status']) ?></span></td><td class="px-4 py-4 uppercase text-violet-200"><?= h($user['role']) ?></td><td class="px-4 py-4 text-[10px] text-slate-500"><?= h(date('d M Y',strtotime((string)$user['created_at'].' UTC'))) ?></td><td class="px-4 py-4 font-bold"><?= h(format_money((int)$user['balance_minor'])) ?></td><td class="px-4 py-4"><?php if((int)$user['id']!== (int)$current['id'] && $user['role']!=='admin'): ?><form method="post" action="<?= h(app_url('index.php?action=admin-user-toggle')) ?>" data-confirm="<?= $user['status']==='active'?'Suspend':'Reactivate' ?> this player account?"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= h($user['id']) ?>"><button class="rounded-lg border border-white/10 px-3 py-2 text-[10px] font-bold <?= $user['status']==='active'?'text-rose-300':'text-neon-400' ?>"><?= $user['status']==='active'?'Suspend':'Reactivate' ?></button></form><?php else: ?><span class="text-[10px] text-slate-600">Protected</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
    <?php if(!$users): ?><p class="p-8 text-center text-xs text-slate-500">No accounts match this search.</p><?php endif; ?>
    <?php if($pageCount>1): ?><nav class="flex gap-2 border-t border-white/[.08] p-4"><?php for($n=1;$n<=$pageCount;$n++): ?><a class="rounded-lg border px-3 py-2 text-xs <?= $n===$pageNumber?'border-violet-400/50 text-violet-200':'border-white/10 text-slate-400' ?>" href="<?= h(app_url('index.php?'.http_build_query(['page'=>'admin-users','q'=>$search,'status'=>$statusFilter,'p'=>$n]))) ?>"><?= h($n) ?></a><?php endfor; ?></nav><?php endif; ?>
  </div>
  <section class="glass-card mt-5 rounded-2xl p-5"><div class="flex items-center justify-between"><div><p class="text-[10px] font-black uppercase tracking-widest text-violet-300">Team directory</p><h2 class="mt-1 text-lg font-black">Teams</h2></div><span class="text-xs text-slate-500"><?= h(number_format($teamCount)) ?> teams</span></div>
    <?php if(!$teams): ?><p class="mt-4 text-xs text-slate-500">No teams created yet.</p><?php else: ?><div class="table-wrap mt-4"><table class="w-full text-left text-xs"><thead class="text-[10px] uppercase tracking-wider text-slate-500"><tr><th class="pb-3">Team</th><th class="pb-3">Captain</th><th class="pb-3">Members</th><th class="pb-3">Created</th></tr></thead><tbody class="divide-y divide-white/[.07]"><?php foreach($teams as $team): ?><tr><td class="py-3 font-bold"><?= h($team['name']) ?></td><td class="py-3 text-slate-400"><?= h($team['captain_name']) ?></td><td class="py-3"><?= h($team['member_count']) ?>/4</td><td class="py-3 text-[10px] text-slate-500"><?= h(date('d M Y',strtotime((string)$team['created_at'].' UTC'))) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
  </section>
</main>
